import{_ as t,o,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Cloud Governance domain maturity scale (AB#6459)","description":"","frontmatter":{},"headers":[],"relativePath":"design/governance-domain-maturity-scale.md","filePath":"design/governance-domain-maturity-scale.md"}'),n={name:"design/governance-domain-maturity-scale.md"};function s(d,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="cloud-governance-domain-maturity-scale-ab-6459" tabindex="-1">Cloud Governance domain maturity scale (AB#6459) <a class="header-anchor" href="#cloud-governance-domain-maturity-scale-ab-6459" aria-label="Permalink to &quot;Cloud Governance domain maturity scale (AB#6459)&quot;">​</a></h1><h2 id="the-two-maturity-numbers-this-repo-now-produces-and-why-they-are-not-the-same-one" tabindex="-1">The two maturity numbers this repo now produces, and why they are not the same one <a class="header-anchor" href="#the-two-maturity-numbers-this-repo-now-produces-and-why-they-are-not-the-same-one" aria-label="Permalink to &quot;The two maturity numbers this repo now produces, and why they are not the same one&quot;">​</a></h2><p>Azure Scout produces two different &quot;maturity&quot; figures, on two different scales, for two different frameworks. This document exists so neither is ever mistaken for the other, and so a report never puts them on the same axis as if they were comparable.</p><table tabindex="0"><thead><tr><th></th><th>WAF Maturity Model</th><th>Cloud Governance domain score</th></tr></thead><tbody><tr><td>Framework</td><td>Well-Architected Framework (5 pillars)</td><td>CAF Govern (7 risk categories)</td></tr><tr><td>Scale</td><td>1-5, Microsoft-published level <strong>names</strong> and focus descriptions</td><td>1-10, entirely Scout&#39;s own scale</td></tr><tr><td>Source of the banding</td><td><code>Get-MaturityLevel.ps1</code> — Scout&#39;s own even 20-point split of the 0-100 pillar score (Microsoft publishes no numeric threshold; see <code>docs/design/waf-maturity-model-mapping.md</code>)</td><td><code>Get-GovernanceDomainScore.ps1</code> — Scout&#39;s own linear /10 mapping of the 0-100 domain score</td></tr><tr><td>Underlying evaluation</td><td>The same WAF pillar rule files (<code>waf.reliability</code>, <code>waf.security</code>, <code>waf.cost</code>, <code>waf.operational</code>, <code>waf.performance</code>) <code>Get-Score</code> already scores for the five WAF pillar assessments and <code>LandingZone</code></td><td>The seven <code>caf.govern.*.yaml</code> rule files (<code>docs/frameworks/cloud-governance-question-set.md</code>, AB#6811)</td></tr><tr><td>Why this scale</td><td>WAF publishes qualitative level names (&quot;Establish a solid foundation on Azure&quot; … &quot;Future-proof with agility&quot;) that Scout relabels a percentage into</td><td>CAF Govern publishes <strong>no</strong> maturity model or level scheme at all — there is nothing Microsoft-published to relabel, so Scout had to invent a scale outright</td></tr></tbody></table><p><strong>Both are relabelings of a percentage <code>Get-Score</code> already computed — neither runs a second rule-evaluation pass.</strong> <code>Get-MaturityLevel</code> and <code>Get-GovernanceDomainScore</code> are pure functions over <code>Get-Score</code>&#39;s output; a rule file is never duplicated for either.</p><h2 id="which-one-ab-6459-uses-and-why" tabindex="-1">Which one AB#6459 uses, and why <a class="header-anchor" href="#which-one-ab-6459-uses-and-why" aria-label="Permalink to &quot;Which one AB#6459 uses, and why&quot;">​</a></h2><p>AB#6459 asks for &quot;a 1-10 domain maturity score across the seven governance domains.&quot; That is <strong>not</strong> WAF&#39;s 5-level model — it is a new scale for the Cloud Governance framework specifically, because:</p><ol><li><strong>CAF Govern has no published maturity model to reuse.</strong> WAF&#39;s 5-level model is a Microsoft artifact Scout relabels; nothing equivalent exists for CAF Govern&#39;s five-step/seven-category structure (<code>docs/frameworks/cloud-governance-question-set.md</code>). A 1-10 scale here is unavoidably Scout&#39;s own invention, exactly as the 20-point WAF banding is Scout&#39;s own invention layered onto Microsoft&#39;s level <strong>names</strong> — the difference is Cloud Governance gets no Microsoft names to layer onto at all.</li><li><strong>1-10, not 0-10 or a repeat of WAF&#39;s 1-5.</strong> Ten points gives finer resolution than a five-way WAF-style band across seven domains that otherwise read too coarsely against each other on a report page (a five-level band collapses roughly 3 rule outcomes into indistinguishable territory for domains carrying only 2-4 rules, e.g. Regulatory Compliance and Resource Management). The floor is 1, not 0: a domain that was genuinely scored (at least one Pass/Partial/Fail rule ran) always carries some evidence, even if every rule failed, so its number should never collapse to the same &quot;0&quot; a chart axis default would show for an unscored domain — that ambiguity is exactly the false-pass-adjacent failure mode this design avoids.</li></ol><h2 id="the-mapping" tabindex="-1">The mapping <a class="header-anchor" href="#the-mapping" aria-label="Permalink to &quot;The mapping&quot;">​</a></h2><p><code>ConvertTo-ScoutGovernanceScale</code> (<code>src/assess/engine/Get-GovernanceDomainScore.ps1</code>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Score1To10 = Max(1, Min(10, Round(PercentScore / 10)))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>Percentage score</th><th>1-10 score</th></tr></thead><tbody><tr><td>0-4%</td><td>1 (floored, never 0)</td></tr><tr><td>5-14%</td><td>1</td></tr><tr><td>15-24%</td><td>2</td></tr><tr><td>…</td><td>…</td></tr><tr><td>95-100%</td><td>10</td></tr></tbody></table><p>The same helper converts both the per-domain scores and the overall Cloud Governance framework headline score (<code>Get-Score</code>&#39;s <code>Frameworks[Framework=&#39;Cloud Governance&#39;].Score</code>, itself the AreaWeight-weighted mean of the seven domains, AB#5087), so the headline number and the seven domain numbers can never use different arithmetic and silently disagree.</p><h2 id="what-a-tenant-with-zero-governance-data-renders-as" tabindex="-1">What a tenant with zero governance data renders as <a class="header-anchor" href="#what-a-tenant-with-zero-governance-data-renders-as" aria-label="Permalink to &quot;What a tenant with zero governance data renders as&quot;">​</a></h2><p>This is the specific false-pass class AB#6839/#6844/#6845 exist to kill, and it applies here identically:</p><ul><li>A domain where <strong>every</strong> rule is <code>Manual</code>/<code>Unknown</code>/<code>Error</code> has <code>Get-Score</code>&#39;s scoring denominator at 0, so <code>Areas[].Score</code> is <code>$null</code>.</li><li><code>Get-GovernanceDomainScore</code> sets <code>Score = $null</code> and <code>NotAssessed = $true</code> for that domain — <strong>never</strong> a fabricated <code>1</code> (which would read as &quot;assessed, worst&quot;) and <strong>never</strong> a fabricated <code>10</code> (which would read as &quot;assessed, perfect&quot;).</li><li><code>Export-GovernanceReport.ps1</code> renders <code>NotAssessed</code> domains as the literal text <strong>&quot;Not assessed&quot;</strong> in the domain table, plots them as a <strong>gap (<code>null</code>)</strong> in the radar line rather than drawing a <code>0</code> vertex (a <code>0</code> on a 1-10 radar visually reads as &quot;worst score&quot;, the exact misleading signal this exists to prevent — see the renderer&#39;s own header comment), and surfaces a dedicated callout banner naming every not-assessed domain above the radar/heatmap.</li><li>If a collect/scoring run never loaded the <code>caf.govern.*.yaml</code> rule files at all (e.g. a narrower assessment that does not include them), <code>Export-GovernanceReport.ps1</code> renders all seven domains as &quot;Not assessed&quot; rather than an empty page — absence is visible, never silent.</li></ul><p>A tenant with genuinely zero policy assignments, zero budgets, and zero resource locks scores <strong>low</strong> on the domains those rules cover (percentage near 0%, banded to <code>1</code>) — that is a real, scored <code>Fail</code>, not <code>NotAssessed</code>. <code>NotAssessed</code> is reserved for &quot;Scout could not evaluate this at all&quot; (every rule manual/errored/no data collected), never for &quot;Scout evaluated this and it failed.&quot;</p>',17)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
